//! Graph-owned construction and validation of durable release intents.
//!
//! The caller supplies an already-resolved selection.  This deliberately does
//! not call `plan_version` or `plan_publish`: received-intent validation must
//! compare an approval, not silently make a fresh planning decision.

use std::collections::{BTreeMap, BTreeSet};

use callisto_model::{
    CanonicalTranscript, CommandRunner, ExecutionTrustProfileV1, PublishTarget, ReleaseInputComponentV1,
    ReleaseInputSnapshotV1, ReleaseIntentV1, ReleaseOperation, ReleaseOperationId, ReleasePackageId,
    SemanticInputDigest, SourceIdentity, Version,
};
use callisto_vcs::GitDataSource;

use crate::{DependencyResolver, GraphError, Workspace};

/// Exact package/version values selected by a preceding release decision.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ReleaseSelection {
    versions: BTreeMap<ReleasePackageId, Version>,
}

impl ReleaseSelection {
    pub fn new(versions: BTreeMap<ReleasePackageId, Version>) -> Self {
        Self { versions }
    }

    pub fn versions(&self) -> &BTreeMap<ReleasePackageId, Version> {
        &self.versions
    }
}

/// In-memory proof that an intent was rebuilt against one workspace.
///
/// Its private field, lack of `Clone`, and lack of serialization are
/// intentional: callers cannot forge or transfer this capability.
#[derive(Debug)]
pub struct ValidatedReleaseIntent {
    intent: ReleaseIntentV1,
}

impl ValidatedReleaseIntent {
    pub fn intent(&self) -> &ReleaseIntentV1 {
        &self.intent
    }
}

/// Builds a canonical intent using read-only workspace observation only.
pub fn build_release_intent<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    source: SourceIdentity,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<ReleaseIntentV1, GraphError> {
    match trust_profile {
        ExecutionTrustProfileV1::GitCommit => {
            let git = ws.git_access();
            if !git.has_clean_detached_head()? || source != (SourceIdentity::GitCommit { sha: git.head_sha()? }) {
                return Err(GraphError::ReleaseIntentStale);
            }
        }
        // A hermetic release needs a closed-root observer. It is safer to
        // reject this profile until graph owns that complete observation than
        // to accidentally bless a Git-derived projection as hermetic.
        ExecutionTrustProfileV1::HermeticContent => return Err(GraphError::ReleaseIntentStale),
    }
    let (snapshot, operations) = derive_release_inputs(ws, selection, source)?;
    ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_error| GraphError::ReleaseIntentStale)
}

/// Rebuilds the snapshot and exact DAG from the supplied workspace. This does
/// not invoke either planner and does not execute the rebuilt graph.
pub fn validate_release_intent<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent, GraphError> {
    // A received source identity is evidence to check, never input trusted by
    // validation.  Hermetic verification needs its own closed-root observer;
    // until that exists it cannot obtain this Git-backed capability.
    let observed_source = match received.trust_profile {
        ExecutionTrustProfileV1::GitCommit => SourceIdentity::GitCommit {
            sha: ws.git_access().head_sha()?,
        },
        ExecutionTrustProfileV1::HermeticContent => return Err(GraphError::ReleaseIntentStale),
    };
    let expected = build_release_intent(ws, selection, observed_source, received.trust_profile)?;
    if expected != received {
        return Err(GraphError::ReleaseIntentStale);
    }
    Ok(ValidatedReleaseIntent { intent: received })
}

fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    source: SourceIdentity,
) -> Result<(ReleaseInputSnapshotV1, Vec<ReleaseOperation>), GraphError> {
    let mut components = Vec::new();
    let mut component_kinds = BTreeSet::new();
    let mut selected = BTreeMap::new();

    for package in ws.graph.packages() {
        for ecosystem in package
            .canonical_manifests()
            .map(|m| m.ecosystem())
            .collect::<BTreeSet<_>>()
        {
            let id =
                ReleasePackageId::new(ecosystem, package.id.name()).map_err(|_error| GraphError::ReleaseIntentStale)?;
            if let Some(version) = selection.versions().get(&id) {
                selected.insert(id, (package, version.clone()));
            }
        }
    }
    for id in selection.versions().keys() {
        if !selected.contains_key(id) {
            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
        }
    }

    // These policies affect release selection/DAG policy. Store a digest only.
    push_component(
        &mut components,
        &mut component_kinds,
        "policy.cascade",
        format!("{:?}", ws.config.cascade),
    );
    push_component(
        &mut components,
        &mut component_kinds,
        "policy.validation",
        format!("{:?}", ws.config.validation),
    );
    push_component(
        &mut components,
        &mut component_kinds,
        "policy.groups",
        format!("{:?}", ws.config.groups),
    );
    for (key, registry) in &ws.config.registries {
        let binding = registry
            .url
            .as_deref()
            .map(|url| normalize_registry_url(key.as_str(), url))
            .transpose()?
            .unwrap_or_else(|| "default".to_string());
        push_component(
            &mut components,
            &mut component_kinds,
            format!("registry-binding:{}", key.as_str()),
            format!("{}:{binding}", registry.kind.prefix()),
        );
    }

    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
    for (id, (package, version)) in selected {
        let mut package_input = CanonicalTranscript::semantic_input_v1();
        package_input.push_str("package.id", &id.to_string());
        package_input.push_str("package.version", version.render());
        for manifest in &package.manifests {
            let bytes = std::fs::read(ws.root.join(&manifest.path)).map_err(|error| GraphError::ReleaseInputRead {
                path: manifest.path.clone(),
                message: error.to_string(),
            })?;
            package_input.push_str("manifest.path", &manifest.path.display().to_string());
            package_input.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
            package_input.push_str("manifest.role", &format!("{:?}", manifest.role));
            package_input.push_str("manifest.format", &format!("{:?}", manifest.format));
        }
        package_input.push_str("package.trigger", &format!("{:?}", package.release_trigger));
        package_input.push_str(
            "package.tag",
            &package
                .tag_template
                .as_ref()
                .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
        );

        let mut publishes = Vec::new();
        let mut has_target = false;
        let mut has_forge_release = false;
        for target in &package.publish_to {
            match target {
                PublishTarget::None => {}
                PublishTarget::GitHubRelease => {
                    has_target = true;
                    has_forge_release = true;
                    package_input.push_str("package.target", "github-release");
                }
                _ => {
                    has_target = true;
                    package_input.push_str("package.target", &target_fingerprint(target)?);
                    if target.ecosystem() == Some(id.ecosystem()) {
                        if let Some(key) = target.registry_key() {
                            let operation = ReleaseOperation::registry_publish(
                                id.clone(),
                                version.clone(),
                                key.as_str().to_string(),
                                Vec::new(),
                            )
                            .map_err(|_error| GraphError::ReleaseIntentStale)?;
                            publishes.push(operation.id().clone());
                            operations.insert(operation.id().clone(), operation);
                        }
                    }
                }
            }
        }
        push_fingerprint(
            &mut components,
            &mut component_kinds,
            format!("package:{id}"),
            SemanticInputDigest::from_transcript(&package_input),
        );
        if has_target {
            publishes.sort();
            let tag = ReleaseOperation::tag(id.clone(), version.clone(), publishes)
                .map_err(|_error| GraphError::ReleaseIntentStale)?;
            let tag_id = tag.id().clone();
            operations.insert(tag_id.clone(), tag);
            if has_forge_release {
                let forge = ReleaseOperation::forge_release(id, version, vec![tag_id])
                    .map_err(|_error| GraphError::ReleaseIntentStale)?;
                operations.insert(forge.id().clone(), forge);
            }
        }
    }
    Ok((
        ReleaseInputSnapshotV1::new(source, components),
        operations.into_values().collect(),
    ))
}

fn push_component(
    components: &mut Vec<ReleaseInputComponentV1>,
    kinds: &mut BTreeSet<String>,
    kind: impl Into<String>,
    value: String,
) {
    let kind = kind.into();
    assert!(
        kinds.insert(kind.clone()),
        "release snapshot component kinds must be unique"
    );
    components.push(ReleaseInputComponentV1 {
        kind,
        fingerprint: digest_text("component", &value),
    });
}

fn push_fingerprint(
    components: &mut Vec<ReleaseInputComponentV1>,
    kinds: &mut BTreeSet<String>,
    kind: impl Into<String>,
    fingerprint: SemanticInputDigest,
) {
    let kind = kind.into();
    assert!(
        kinds.insert(kind.clone()),
        "release snapshot component kinds must be unique"
    );
    components.push(ReleaseInputComponentV1 { kind, fingerprint });
}

fn digest_text(tag: &str, text: &str) -> SemanticInputDigest {
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_str(tag, text);
    SemanticInputDigest::from_transcript(&transcript)
}

fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_bytes(tag, bytes);
    SemanticInputDigest::from_transcript(&transcript)
}

fn target_fingerprint(target: &PublishTarget) -> Result<String, GraphError> {
    let endpoint = |registry, value: Option<&String>| {
        value
            .map(|url| normalize_registry_url(registry, url))
            .transpose()
            .map(|value| value.unwrap_or_else(|| "default".to_string()))
    };
    match target {
        PublishTarget::CratesIo => Ok(";target=crates-io".to_string()),
        PublishTarget::Npm { registry, access } => Ok(format!(
            ";target=npm:{}:{access:?}",
            endpoint("npm", registry.as_ref())?
        )),
        PublishTarget::Pypi { index } => Ok(format!(";target=pypi:{}", endpoint("pypi", index.as_ref())?)),
        PublishTarget::NuGet { source } => Ok(format!(";target=nuget:{}", endpoint("nuget", source.as_ref())?)),
        PublishTarget::GitHubRelease => Ok(";target=github-release".to_string()),
        PublishTarget::None => Ok(";target=none".to_string()),
        #[allow(unreachable_patterns)]
        _ => Ok(";target=future".to_string()),
    }
}

/// Normalizes only scheme, authority (including explicit port), and path.
/// Userinfo, queries, and fragments are rejected before they can influence a
/// durable binding fingerprint.
fn normalize_registry_url(registry: &str, raw: &str) -> Result<String, GraphError> {
    let (scheme, remainder) = raw.split_once("://").ok_or_else(|| GraphError::UnsafeRegistryBinding {
        registry: registry.to_string(),
        reason: "missing scheme",
    })?;
    if scheme.is_empty() || remainder.is_empty() {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "empty scheme or authority",
        });
    }
    if remainder.contains('@') {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "userinfo is forbidden",
        });
    }
    if remainder.contains('?') {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "query string is forbidden",
        });
    }
    if remainder.contains('#') {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "fragment is forbidden",
        });
    }
    let (authority, path) = remainder.split_once('/').unwrap_or((remainder, ""));
    if authority.is_empty() || authority.chars().any(char::is_whitespace) {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "invalid authority",
        });
    }
    let suffix = if path.is_empty() {
        String::new()
    } else {
        format!("/{path}")
    };
    Ok(format!(
        "{}://{}{}",
        scheme.to_ascii_lowercase(),
        authority.to_ascii_lowercase(),
        suffix
    ))
}

