        let result = match self.publish_with_retry(&package, &version, permit) {
            Ok(PublishOutcome::Published) => PublishAttemptResult::Published,
            Ok(PublishOutcome::AlreadyPublished) => PublishAttemptResult::AlreadyPublished,
