 95	fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
 96	    ws: &Workspace<'_, R, D>,
 97	    selection: &ReleaseSelection,
 98	    source: SourceIdentity,
 99	) -> Result<(ReleaseInputSnapshotV1, Vec<ReleaseOperation>), GraphError> {
100	    let mut components = Vec::new();
101	    let mut component_kinds = BTreeSet::new();
102	    let mut selected = BTreeMap::new();
103	
104	    for package in ws.graph.packages() {
105	        for ecosystem in package
106	            .canonical_manifests()
107	            .map(|m| m.ecosystem())
108	            .collect::<BTreeSet<_>>()
109	        {
110	            let id =
111	                ReleasePackageId::new(ecosystem, package.id.name()).map_err(|_error| GraphError::ReleaseIntentStale)?;
112	            if let Some(version) = selection.versions().get(&id) {
113	                selected.insert(id, (package, version.clone()));
114	            }
115	        }
116	    }
117	    for id in selection.versions().keys() {
118	        if !selected.contains_key(id) {
119	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
120	        }
121	    }
122	
123	    // These policies affect release selection/DAG policy. Store a digest only.
124	    push_component(
125	        &mut components,
126	        &mut component_kinds,
127	        "policy.cascade",
128	        format!("{:?}", ws.config.cascade),
129	    );
130	    push_component(
131	        &mut components,
132	        &mut component_kinds,
133	        "policy.validation",
134	        format!("{:?}", ws.config.validation),
135	    );
136	    push_component(
137	        &mut components,
138	        &mut component_kinds,
139	        "policy.groups",
140	        format!("{:?}", ws.config.groups),
141	    );
142	    for (key, registry) in &ws.config.registries {
143	        let binding = registry
144	            .url
145	            .as_deref()
146	            .map(|url| normalize_registry_url(key.as_str(), url))
147	            .transpose()?
148	            .unwrap_or_else(|| "default".to_string());
149	        push_component(
150	            &mut components,
151	            &mut component_kinds,
152	            format!("registry-binding:{}", key.as_str()),
153	            format!("{}:{binding}", registry.kind.prefix()),
154	        );
155	    }
156	
157	    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
158	    for (id, (package, version)) in selected {
159	        let mut package_input = CanonicalTranscript::semantic_input_v1();
160	        package_input.push_str("package.id", &id.to_string());
161	        package_input.push_str("package.version", version.render());
162	        for manifest in &package.manifests {
163	            let bytes = std::fs::read(ws.root.join(&manifest.path)).map_err(|error| GraphError::ReleaseInputRead {
164	                path: manifest.path.clone(),
165	                message: error.to_string(),
166	            })?;
167	            package_input.push_str("manifest.path", &manifest.path.display().to_string());
168	            package_input.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
169	            package_input.push_str("manifest.role", &format!("{:?}", manifest.role));
170	            package_input.push_str("manifest.format", &format!("{:?}", manifest.format));
171	        }
172	        package_input.push_str("package.trigger", &format!("{:?}", package.release_trigger));
173	        package_input.push_str(
174	            "package.tag",
175	            &package
176	                .tag_template
177	                .as_ref()
178	                .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
179	        );
180	
181	        let mut publishes = Vec::new();
182	        let mut has_target = false;
183	        let mut has_forge_release = false;
184	        for target in &package.publish_to {
185	            match target {
186	                PublishTarget::None => {}
187	                PublishTarget::GitHubRelease => {
188	                    has_target = true;
189	                    has_forge_release = true;
190	                    package_input.push_str("package.target", "github-release");
191	                }
192	                _ => {
193	                    has_target = true;
194	                    package_input.push_str("package.target", &target_fingerprint(target)?);
195	                    if target.ecosystem() == Some(id.ecosystem()) {
196	                        if let Some(key) = target.registry_key() {
197	                            let operation = ReleaseOperation::registry_publish(
198	                                id.clone(),
199	                                version.clone(),
200	                                key.as_str().to_string(),
201	                                Vec::new(),
202	                            )
203	                            .map_err(|_error| GraphError::ReleaseIntentStale)?;
204	                            publishes.push(operation.id().clone());
205	                            operations.insert(operation.id().clone(), operation);
206	                        }
207	                    }
208	                }
209	            }
210	        }
211	        push_fingerprint(
212	            &mut components,
213	            &mut component_kinds,
214	            format!("package:{id}"),
215	            SemanticInputDigest::from_transcript(&package_input),
216	        );
217	        if has_target {
218	            publishes.sort();
219	            let tag = ReleaseOperation::tag(id.clone(), version.clone(), publishes)
220	                .map_err(|_error| GraphError::ReleaseIntentStale)?;
221	            let tag_id = tag.id().clone();
222	            operations.insert(tag_id.clone(), tag);
223	            if has_forge_release {
224	                let forge = ReleaseOperation::forge_release(id, version, vec![tag_id])
225	                    .map_err(|_error| GraphError::ReleaseIntentStale)?;
226	                operations.insert(forge.id().clone(), forge);
227	            }
228	        }
229	    }
230	    Ok((
231	        ReleaseInputSnapshotV1::new(source, components),
232	        operations.into_values().collect(),
233	    ))
234	}
