663	fn validate_operations(operations: &[ReleaseOperation]) -> Result<(), ReleaseIntentError> {
664	    let mut ids = BTreeSet::new();
665	    for operation in operations {
666	        if !ids.insert(operation.id.clone()) {
667	            return Err(ReleaseIntentError::DuplicateOperation {
668	                id: Box::new(operation.id.clone()),
669	            });
670	        }
671	    }
672	    for operation in operations {
673	        if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1]) {
674	            return Err(ReleaseIntentError::NonCanonicalPrerequisiteOrder {
675	                id: Box::new(operation.id.clone()),
676	            });
677	        }
678	        for prerequisite in &operation.prerequisites {
679	            if prerequisite == &operation.id {
680	                return Err(ReleaseIntentError::SelfPrerequisite {
681	                    id: Box::new(operation.id.clone()),
682	                });
683	            }
684	            if !ids.contains(prerequisite) {
685	                return Err(ReleaseIntentError::UnknownPrerequisite {
686	                    id: Box::new(operation.id.clone()),
687	                    prerequisite: Box::new(prerequisite.clone()),
688	                });
689	            }
690	        }
691	    }
692	    let edges: BTreeMap<_, _> = operations
693	        .iter()
694	        .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
695	        .collect();
696	    let canonical = stable_kahn_order(&edges)?;
697	    if operations.iter().map(ReleaseOperation::id).ne(canonical.iter()) {
698	        return Err(ReleaseIntentError::NonCanonicalOperationOrder);
699	    }
700	    Ok(())
701	}
