 56	
 57	    /// Checks the release-source invariant used by durable execution.
 58	    ///
 59	    /// A branch checkout is intentionally not accepted: a durable intent is
 60	    /// bound to one immutable commit rather than a moving ref. `git status`
 61	    /// includes tracked changes and non-ignored untracked files, so generated
 62	    /// files covered by the repository's explicit ignore policy do not alter
 63	    /// the source identity.
 64	    pub fn has_clean_detached_head(&self) -> Result<bool, VcsError> {
 65	        let symbolic = self.runner.run("git", &["symbolic-ref", "-q", "HEAD"], &self.root)?;
 66	        if symbolic.success() {
 67	            return Ok(false);
 68	        }
 69	
 70	        let status = self.runner.run(
 71	            "git",
 72	            &["status", "--porcelain=v1", "--untracked-files=all"],
 73	            &self.root,
 74	        )?;
 75	        if !status.success() {
 76	            return Err(VcsError::Git(format!(
 77	                "`git status --porcelain=v1 --untracked-files=all` failed in `{}`: {}",
 78	                self.root.display(),
 79	                redact_git_stderr(&status.stderr)
 80	            )));
 81	        }
 82	        Ok(status.stdout_trimmed().is_empty())
 83	    }
 84	}
