 86	/// Compiles `glob` into a [`globset::GlobMatcher`], surfacing a malformed
 87	/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
 88	/// disable filtering (which would match every tag -- see
 89	/// `GitRepository::list_tags`'s own doc comment for why that's a real
 90	/// correctness risk for release tagging).
 91	fn compile_glob(glob: &str) -> Result<globset::GlobMatcher, VcsError> {
 92	    globset::Glob::new(glob)
