 72	/// Rebuilds the snapshot and exact DAG from the supplied workspace. This does
 73	/// not invoke either planner and does not execute the rebuilt graph.
 74	pub fn validate_release_intent<R: CommandRunner, D: DependencyResolver>(
 75	    ws: &Workspace<'_, R, D>,
 76	    selection: &ReleaseSelection,
 77	    received: ReleaseIntentV1,
 78	) -> Result<ValidatedReleaseIntent, GraphError> {
 79	    // A received source identity is evidence to check, never input trusted by
 80	    // validation.  Hermetic verification needs its own closed-root observer;
 81	    // until that exists it cannot obtain this Git-backed capability.
 82	    let observed_source = match received.trust_profile {
 83	        ExecutionTrustProfileV1::GitCommit => SourceIdentity::GitCommit {
 84	            sha: ws.git_access().head_sha()?,
 85	        },
 86	        ExecutionTrustProfileV1::HermeticContent => return Err(GraphError::ReleaseIntentStale),
 87	    };
 88	    let expected = build_release_intent(ws, selection, observed_source, received.trust_profile)?;
 89	    if expected != received {
 90	        return Err(GraphError::ReleaseIntentStale);
 91	    }
 92	    Ok(ValidatedReleaseIntent { intent: received })
 93	}
