703	fn stable_kahn_order(
704	    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
705	) -> Result<Vec<ReleaseOperationId>, ReleaseIntentError> {
706	    let mut remaining: BTreeMap<_, usize> = prerequisites
707	        .iter()
708	        .map(|(id, prerequisites)| (id.clone(), prerequisites.len()))
709	        .collect();
710	    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
711	    for (id, prerequisites) in prerequisites {
712	        for prerequisite in prerequisites {
713	            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
714	        }
715	    }
716	    let mut ready: BTreeSet<_> = remaining
717	        .iter()
718	        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
719	        .collect();
720	    let mut ordered = Vec::with_capacity(prerequisites.len());
721	    while let Some(id) = ready.pop_first() {
722	        ordered.push(id.clone());
723	        for dependent in dependents.get(&id).into_iter().flatten() {
724	            let count = remaining.get_mut(dependent).expect("known DAG node");
725	            *count -= 1;
726	            if *count == 0 {
727	                ready.insert(dependent.clone());
728	            }
729	        }
730	    }
731	    if ordered.len() != prerequisites.len() {
732	        let id = remaining
733	            .into_iter()
734	            .find_map(|(id, count)| (count != 0).then_some(id))
735	            .expect("a nonempty cyclic DAG has a remaining node");
