103	            let mut ecosystems_by_id: BTreeMap<(String, PackageId), BTreeSet<Ecosystem>> = BTreeMap::new();
104	            for ((eco, name), id) in &graph.identity().prefixed {
105	                ecosystems_by_id
106	                    .entry((name.clone(), id.clone()))
107	                    .or_default()
